begin;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(char_length(display_name) between 1 and 100), role text not null default 'student' check(role in ('student','teacher','admin')), created_at timestamptz not null default now());
create table public.doubts (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id), question text not null check(char_length(question) between 1 and 4000), subject text not null, status text not null default 'open' check(status in ('open','answered')), created_at timestamptz not null default now());
create table public.replies (id uuid primary key default gen_random_uuid(), doubt_id uuid not null references public.doubts(id) on delete cascade, author_id uuid not null references public.profiles(id), body text not null check(char_length(body) between 1 and 4000), created_at timestamptz not null default now());
create table public.notices (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id), title text not null, body text not null, pinned boolean not null default false, created_at timestamptz not null default now());
create table public.polls (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id), question text not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.poll_options (id uuid primary key default gen_random_uuid(), poll_id uuid not null references public.polls(id) on delete cascade, label text not null, unique(poll_id,id));
create table public.poll_votes (poll_id uuid not null, option_id uuid not null, voter_id uuid not null references public.profiles(id), primary key(poll_id,voter_id), foreign key(poll_id,option_id) references public.poll_options(poll_id,id) on delete cascade);
create table public.messages (id uuid primary key default gen_random_uuid(), sender_id uuid not null references public.profiles(id), recipient_id uuid not null references public.profiles(id), body text not null check(char_length(body) between 1 and 4000), created_at timestamptz not null default now(), check(sender_id <> recipient_id));
create table public.resources (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id), title text not null, url text not null check(url ~ '^https://'), subject text not null, created_at timestamptz not null default now());
alter table public.profiles enable row level security; revoke all on public.profiles from anon, authenticated; grant select on public.profiles to authenticated;
alter table public.doubts enable row level security; revoke all on public.doubts from anon, authenticated; grant select on public.doubts to authenticated;
alter table public.replies enable row level security; revoke all on public.replies from anon, authenticated; grant select on public.replies to authenticated;
alter table public.notices enable row level security; revoke all on public.notices from anon, authenticated; grant select on public.notices to authenticated;
alter table public.polls enable row level security; revoke all on public.polls from anon, authenticated; grant select on public.polls to authenticated;
alter table public.poll_options enable row level security; revoke all on public.poll_options from anon, authenticated; grant select on public.poll_options to authenticated;
alter table public.poll_votes enable row level security; revoke all on public.poll_votes from anon, authenticated; grant select on public.poll_votes to authenticated;
alter table public.messages enable row level security; revoke all on public.messages from anon, authenticated; grant select on public.messages to authenticated;
alter table public.resources enable row level security; revoke all on public.resources from anon, authenticated; grant select on public.resources to authenticated;
grant insert(id,display_name) on public.profiles to authenticated;
grant update(display_name) on public.profiles to authenticated;
create policy profiles_read on public.profiles for select to authenticated using (true);
create policy profiles_create on public.profiles for insert to authenticated with check(id=(select auth.uid()) and role='student');
create policy profiles_edit on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy doubts_read on public.doubts for select to authenticated using (true);
create policy replies_read on public.replies for select to authenticated using (true);
create policy notices_read on public.notices for select to authenticated using (true);
create policy polls_read on public.polls for select to authenticated using (true);
create policy poll_options_read on public.poll_options for select to authenticated using (true);
create policy resources_read on public.resources for select to authenticated using (true);
grant insert(author_id,question,subject) on public.doubts to authenticated;
grant insert(doubt_id,author_id,body) on public.replies to authenticated;
create policy doubts_create on public.doubts for insert to authenticated with check(author_id=(select auth.uid()));
create policy replies_create on public.replies for insert to authenticated with check(author_id=(select auth.uid()));
grant update(status) on public.doubts to authenticated;
create policy doubts_status on public.doubts for update to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('teacher','admin'))) with check (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('teacher','admin')));
grant insert on public.notices to authenticated; create policy notices_create on public.notices for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('teacher','admin')));
grant insert on public.polls to authenticated; create policy polls_create on public.polls for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('teacher','admin')));
grant insert on public.resources to authenticated; create policy resources_create on public.resources for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('teacher','admin')));
grant update(active) on public.polls to authenticated;
create policy polls_close on public.polls for update to authenticated using(author_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('teacher','admin'))) with check(author_id=(select auth.uid()));
grant insert(poll_id,label) on public.poll_options to authenticated;
create policy options_create on public.poll_options for insert to authenticated with check(exists(select 1 from public.polls p join public.profiles u on u.id=p.author_id where p.id=poll_id and p.author_id=(select auth.uid()) and u.role in ('teacher','admin') and p.active));
grant insert(poll_id,option_id,voter_id) on public.poll_votes to authenticated;
create policy votes_read on public.poll_votes for select to authenticated using(voter_id=(select auth.uid()));
create policy votes_create on public.poll_votes for insert to authenticated with check(voter_id=(select auth.uid()) and exists(select 1 from public.polls p where p.id=poll_id and p.active));
grant insert(sender_id,recipient_id,body) on public.messages to authenticated;
create policy messages_read on public.messages for select to authenticated using(sender_id=(select auth.uid()) or recipient_id=(select auth.uid()));
create policy messages_send on public.messages for insert to authenticated with check(sender_id=(select auth.uid()));
create index messages_sender_idx on public.messages(sender_id);
create index messages_recipient_idx on public.messages(recipient_id);
create index replies_doubt_idx on public.replies(doubt_id);
create index poll_options_poll_idx on public.poll_options(poll_id);
commit;
